import { test, expect } from '@playwright/test';

test.describe('Navigation from home page to example page and back', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com');
  });

  test('should display home page heading and navigate to A/B Testing page', async ({ page }) => {
    const homeHeading = await page.getByRole('heading', { name: 'Welcome to the-internet' });
    await expect(homeHeading).toBeVisible();

    const abTestingLink = await page.getByText('A/B Testing');
    await abTestingLink.click();

    await expect(page).toHaveURL(/.*\/abtest/);
    const abTestingHeading = await page.getByRole('heading', { level: 3 });
    await expect(abTestingHeading).toBeVisible();
  });

  test('should navigate back to home page and display available examples heading', async ({ page }) => {
    await page.getByText('A/B Testing').click();
    await page.goBack();

    const availableExamplesHeading = await page.getByRole('heading', { name: 'Available Examples' });
    await expect(availableExamplesHeading).toBeVisible();
  });
});
